/* global swconf */

importScripts("./assets/js/data/swconf.js");

self.addEventListener("install", (event) => {
  event.waitUntil(install());
});

self.addEventListener("activate", (event) => {
  event.waitUntil(activate());
});

async function install() {
  if (!swconf.purge) {
    try {
      const cache = await caches.open(swconf.cacheName);
      const requests = swconf.resources.map((url) => new Request(url, { cache: "reload" }));
      await cache.addAll(requests);
    } catch {
      // A failed prefetch should still allow the new worker to take over.
    }
  }
  await self.skipWaiting();
}

async function activate() {
  try {
    const names = await caches.keys();
    await Promise.all(
      names
        .filter((name) => /^chirpy-\d+$/.test(name) && name !== swconf.cacheName)
        .map((name) => caches.delete(name))
    );
  } catch {
    // Cache cleanup is best-effort during activation.
  }
  await self.clients.claim();
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (swconf.purge || request.method !== "GET" || request.headers.has("range")) {
    return;
  }

  const url = new URL(request.url);
  const { paths, urlPrefixes } = swconf.interceptor;
  if (
    !["http:", "https:"].includes(url.protocol) ||
    paths.some((path) => url.pathname.startsWith(path)) ||
    urlPrefixes.some((prefix) => url.href.startsWith(prefix))
  ) {
    return;
  }

  const revalidate = request.mode === "navigate" || request.destination === "style";
  if (revalidate && url.origin === self.location.origin) {
    event.respondWith(loadFreshResponse(event));
  } else {
    event.respondWith(loadAsset(event));
  }
});

async function loadFreshResponse(event) {
  const { request } = event;
  let response;
  try {
    response = await fetch(request, { cache: "no-cache" });
  } catch (error) {
    const cached = await cachedResponse(request);
    if (cached) return cached;
    throw error;
  }

  if (response.ok) {
    storeResponse(event, response);
  } else if (response.status === 404 || response.status === 410) {
    event.waitUntil(
      caches.open(swconf.cacheName).then((cache) => cache.delete(request)).catch(() => {})
    );
  }
  return response;
}

async function loadAsset(event) {
  const cached = await cachedResponse(event.request);
  if (cached) return cached;

  const response = await fetch(event.request);
  if (response.ok || response.type === "opaque") storeResponse(event, response);
  return response;
}

function cachedResponse(request) {
  return caches.match(request, { cacheName: swconf.cacheName }).catch(() => undefined);
}

function storeResponse(event, response) {
  const copy = response.clone();
  event.waitUntil(
    caches.open(swconf.cacheName).then((cache) => cache.put(event.request, copy)).catch(() => {})
  );
}
